var apiUtils = require("@node-red/editor-api/lib/util");
var fs = require("fs");
var runtime;
var utilApi = require("@node-red/util");
const { set } = require("grunt");

let parent_backdoors = []
let up = []
let down = []
let parent_child_idx = {}
let collider_paths = {}


var api = module.exports = {
    init: function (_runtime) {
        runtime = _runtime;
    },

    d_separation: async function d_separation(req, res) {
        let parent_child = req.body.parent_child
        let path = req.body.path
        let set = new Set(req.body.set)
        console.log("\n\n")
        let blocked_by_collider = null
        let conditioned_on_descendant = false
        let colliders = []
        let collider_descendants = []
        path.forEach((node_id, l) => {
            if (l >= 1 && l < path.length - 1) {
                previous = path[l - 1]
                current = path[l]
                next = path[l + 1]
                // check if subpath is a collider if not then it is a chain or fork
                let middle_parents = new Set(parent_child[current])
                if (middle_parents.has(previous) && middle_parents.has(next)) {
                    // if set doesn't contain collider then path is blocked
                    // console.log("Collider", current)
                    // console.log("Set has collider ", set.has(current))
                    if (set.has(current) && set.size === 1) {
                        blocked_by_collider === false
                    } else {
                        blocked_by_collider === true
                    }
                    if (!blocked_by_collider) {
                        colliders.push(current)
                    }
                    // check for descendants of collider in current set
                    let collider_node = runtime._.nodes.getNode(current)
                    let adj_desc = collider_node.wires[0].map(wire => {
                        if (set.has(wire)) {
                            collider_descendants.push(wireƒ)
                        }
                        return set.has(wire)
                    })
                    adj_desc = new Set(adj_desc)
                    conditioned_on_descendant = adj_desc.has(true)
                } else {
                    if (set.has(current)) {
                        blocked_by_collider = true
                    }
                }
            }
        })

        path = new Set(path)

        let blocked_by_adj = []
        set.forEach(value => {
            if (path.has(value)) {
                console.log(path, value)
                blocked_by_adj.push(value)
            }
        })



        let is_blocked = false
        if (blocked_by_adj.length > 0) {
            if (blocked_by_collider && !conditioned_on_descendant) {
                is_blocked = true
            } else {
                is_blocked = false
            }
        } else {
            is_blocked = false
        }
        console.log(is_blocked)
        res.send(is_blocked)
    },

    find_backdoors: async function find_backdoors(req, res) {
        colliders = {}
        up = []
        down = []
        parent_child_idx = {}
        collider_paths = {}
        collider_subpath = {}
        console.log("\n\n")
        console.log(req.body)
        parent_child_idx = req.body.parent_child
        let treatments = req.body.treatments
        console.log(parent_child_idx)
        let outcome = req.body.outcomes
        console.log(outcome[0])

        let backdoors = []
        let links = {}
        let set = []
        let backdoor_set = ""

        const result = new Promise((resolve, reject) => {
            let complete_backdoors = []
            parent_backdoors = []
            up = []
            down = []
            for (index in treatments) {
                if (parent_child_idx[treatments]) {
                    let treatment_node = runtime._.nodes.getNode(treatments[index])
                    let backdoors_i = []
                    up.push(treatment_node.id)
                    find_ancestor(treatment_node, treatments[index], outcome[0], backdoors_i, null)
                    up.pop()

                    if (Object.keys(collider_paths).length > 0) {
                        Object.keys(collider_paths).forEach(collider_id => {
                            let path = []
                            // construct upward part of path
                            let collider_node = collider_paths[collider_id]
                            let temp_backdoors = []
                            collider_node.parents_needed.forEach(parent => {
                                let parent_node = runtime._.nodes.getNode(parent)
                                up.push(parent)
                                dfs_help(parent_node, treatments[index], outcome[0], temp_backdoors, collider_id, path)
                                up.pop()
                            })
                            collider_node = { ...collider_node, "subpath": path[0] }
                            collider_paths = { ...collider_paths, [collider_id]: collider_node }
                        })
                    }
                }
                else {
                    console.log("no backdoors to account for")
                }
            }
            resolve(parent_backdoors)
        });
        result.then(parent_backdoors => {
            let res_object = {
                backdoors: parent_backdoors,
                colliders: collider_paths
            }
            res.send(res_object)
        })

    },

}
function dfs_help(node, treatment, outcome, temp_backdoors, collider_id, path) {
    if (node.wires[0].length > 0) {
        node.wires[0].forEach((wire) => {

            if (wire !== treatment && wire !== collider_id) {
                let child_node = runtime._.nodes.getNode(wire)
                console.log("\t pushing down : ", child_node.name, wire)
                down.push(wire)
                dfs_help(child_node, treatment, outcome, temp_backdoors, collider_id, path)
                let popped = down.pop()
                console.log("\t popped: ", child_node.name, popped)
            }
        })
    } else {
        if (node.id === outcome) {
            let collider_subpath = {}
            console.log("\t at leaf node", node.name)
            console.log("\t up: ", up)
            console.log("\t down: ", down)
            console.log("\n")
            collider_subpath = { ...collider_subpath, "up": [...up] }
            collider_subpath = { ...collider_subpath, "down": [...down] }
            path.push(collider_subpath)
            console.log("\t backdoor path of ", collider_subpath)
        }

    }

}

// climb up tree then down tree so climb to health
function find_ancestor(node, treatment, outcome, backdoors_i, visited) {
    console.log("@find ancestor", node.name)
    if (parent_child_idx[node.id]) {
        parent_child_idx[node.id].forEach((parent) => {
            let parent_node = runtime._.nodes.getNode(parent)
            let up_set = new Set(up)
            if (parent_node !== null) {
                console.log("\t pushing up: ", parent_node.name, parent)
                if (up_set.has(parent)) {
                    console.log("\t [CRITICAL]: parent already in set of up")
                } else {
                    up.push(parent)
                    if (up.length >= 2) {
                        visited = up[up.length - 2]
                    } else {
                        visited = null
                    }
                    dfs__path(parent_node, treatment, outcome, backdoors_i, visited)
                    find_ancestor(parent_node, treatment, outcome, parent_child_idx, backdoors_i, visited)
                    console.log("\t popped parent: ", parent_node.name, up.pop())
                }
            }
        })
    } else {
        console.log("\t" + node.name + " has no ancestors")
    }
}

// push next wire to queue if that node has more wires 
// else construct the path [treatment <- parent: (parent,treatment), (parent, wire)]
function dfs__path(node, treatment, outcome, backdoors_i, visited) {
    // if the node is not a leaf node 
    if (node.wires[0].length > 0) {
        node.wires[0].forEach((wire) => {

            if (node.id === outcome) {
                backdoors_i = []
                console.log("\t at leaf node", node.name)
                console.log("\t up: ", up)
                console.log("\t down: ", down)
                console.log("\n")
                backdoors_i = {}
                backdoors_i = { ...backdoors_i, "up": [...up] }
                backdoors_i = { ...backdoors_i, "down": [...down] }
                parent_backdoors.push(backdoors_i)
                backdoors_i = []
            }
            else if (wire !== treatment && wire !== visited) {
                let child_node = runtime._.nodes.getNode(wire)

                console.log("\t pushing down : ", child_node.name, wire)
                down.push(wire)
                dfs__path(child_node, treatment, outcome, backdoors_i)
                let popped = down.pop()
                console.log("\t popped: ", child_node.name, popped)
                if (popped !== treatment && popped !== outcome) {
                    // convert up array to set
                    let up_set = new Set(up)
                    let contains_all_parents = true
                    let parents_needed = []
                    parent_child_idx[popped].forEach((parent) => {
                        if (parent !== treatment && parent !== outcome) {
                            if (!up_set.has(parent)) {
                                contains_all_parents = false
                                parents_needed.push(parent)
                            }
                        }
                    })
                    console.log("\t Contains all parents: ", contains_all_parents)
                    console.log("\t Ancestors: ", parent_child_idx[popped])
                    let temp_visited = popped
                    if (!contains_all_parents) {
                        console.log("\t up : ", up)
                        console.log("\t down : ", down)
                        console.log("\t will find ancestors for possible backdoor path")
                        console.log("\t parents_needed", parents_needed)
                        collider_paths = {
                            ...collider_paths, [popped]: {
                                parents_needed: parents_needed,
                                up: [...up],
                            }
                        }
                    }
                }
            }
        })
    } else {
        if (node.id === outcome) {
            backdoors_i = []
            console.log("\t at leaf node", node.name)
            console.log("\t up: ", up)
            console.log("\t down: ", down)
            console.log("\n")
            backdoors_i = {}
            backdoors_i = { ...backdoors_i, "up": [...up] }
            backdoors_i = { ...backdoors_i, "down": [...down] }
            parent_backdoors.push(backdoors_i)
            backdoors_i = []
        } else {
            backdoors_i = []
        }
        // leaf node
        return
    }
    return
}



